-- Minimal production-shaped schema for disposable local PostgreSQL tests.
create role anon; create role authenticated; create role service_role;
create table public.contacts(id uuid primary key default gen_random_uuid(),email text,phone text,first_name text,stage text default 'new' constraint contacts_stage_check check(stage in ('new','engaged','qualified','recommended','customer','unsubscribed')),source text,utm_source text,utm_medium text,utm_campaign text,utm_content text,marketing_consent_at timestamptz,privacy_notice_accepted_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),internal_notes text,manual_tags text[] not null default '{}',preferences jsonb not null default '{}',assigned_to text,check(email is not null or phone is not null));
create unique index contacts_email on public.contacts(lower(email)) where email is not null;
create table public.conversations(id uuid primary key default gen_random_uuid(),contact_id uuid references public.contacts(id),channel text,status text default 'open',handoff_status text default 'bot',priority text default 'normal',updated_at timestamptz default now(),internal_notes text);
create table public.catalog_products(id uuid primary key default gen_random_uuid(),woocommerce_product_id bigint unique,name text,status text default 'publish',stock_status text default 'instock',price numeric,currency text default 'EUR',synced_at timestamptz default now(),permalink text,stock_quantity integer,product_type text default 'simple');
create table public.product_documents(id uuid primary key default gen_random_uuid(),catalog_product_id uuid constraint product_documents_catalog_product_id_fkey references public.catalog_products(id) on delete cascade,document_type text not null,title text,content text,source_url text,approval_status text default 'draft',reviewed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.contact_events(id uuid primary key default gen_random_uuid(),contact_id uuid references public.contacts(id),event_type text,source text,metadata jsonb default '{}',idempotency_key text unique,occurred_at timestamptz default now());
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid references public.conversations(id),direction text,body text,created_at timestamptz default now());
create table public.inbound_message_buffer(id uuid primary key default gen_random_uuid(),contact_id uuid references public.contacts(id),conversation_id uuid references public.conversations(id),channel text,external_message_id text,normalized_text text,received_at timestamptz default now(),status text default 'pending',processed_at timestamptz,claimed_at timestamptz,attempts integer default 0,last_error text);
create table public.outbound_dispatches(id uuid primary key default gen_random_uuid(),contact_id uuid references public.contacts(id),conversation_id uuid,message_id uuid,channel text,delivery_type text,payload jsonb default '{}',idempotency_key text,status text default 'pending',scheduled_for timestamptz,created_at timestamptz default now(),error_message text,claimed_at timestamptz,attempts integer default 0,last_attempt_at timestamptz);
create table public.follow_ups(id uuid primary key default gen_random_uuid(),contact_id uuid,channel text,status text);
create table public.agent_runs(id uuid primary key default gen_random_uuid(),conversation_id uuid,contact_id uuid,inbound_batch_ids uuid[],agent_role text,status text,decision jsonb,prompt_version text,input_summary text,output_summary text,completed_at timestamptz);
create table public.attribution_touchpoints(id uuid primary key default gen_random_uuid(),contact_id uuid,channel text,source text,campaign text,external_lead_id text,metadata jsonb default '{}');
